INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7675361, 1254447, 65234, '<td valign="top">Really beautiful; I love the color palette and the different geometric shapes of the layers.</td>', 'Really beautiful; I love the color palette and the different geometric shapes of the layers.', '2020-09-25 10:12:26.000000', NULL, 1),
(7675364, 1254337, 65234, '<td valign="top">Simple pattern but very pleasing. Cabinet door, maybe? The diagonals really make this image.</td>', 'Simple pattern but very pleasing. Cabinet door, maybe? The diagonals really make this image.', '2020-09-25 10:18:55.000000', NULL, 1),
(7675365, 1254640, 65234, '<td valign="top">Live the rich colors, especially that teal in the center. Complex, pleasing pattern.</td>', 'Live the rich colors, especially that teal in the center. Complex, pleasing pattern.', '2020-09-25 10:19:51.000000', NULL, 1),
(7675366, 1254601, 65234, '<td valign="top">Soft and dreamy.</td>', 'Soft and dreamy.', '2020-09-25 10:20:20.000000', NULL, 1),
(7675367, 1254258, 65234, '<td valign="top">It does look like that! Really fun image.</td>', 'It does look like that! Really fun image.', '2020-09-25 10:20:52.000000', NULL, 1),
(7675369, 1254419, 65234, '<td valign="top">Very psychedelic.</td>', 'Very psychedelic.', '2020-09-25 10:22:14.000000', NULL, 1),
(7675371, 1254635, 65234, '<td valign="top">It does at that!</td>', 'It does at that!', '2020-09-25 10:25:01.000000', NULL, 1),
(7675372, 1254633, 65234, '<td valign="top">Very complex pattern. Just a hint of color,and it most definitely resembles a doily.</td>', 'Very complex pattern. Just a hint of color,and it most definitely resembles a doily.', '2020-09-25 10:26:31.000000', NULL, 1),
(7675373, 1254400, 65234, '<td valign="top">Yep, I can see that. Interesting image.</td>', 'Yep, I can see that. Interesting image.', '2020-09-25 10:28:01.000000', NULL, 1),
(7675374, 1254316, 65234, '<td valign="top">Like a soft, swirly Celtic knot.</td>', 'Like a soft, swirly Celtic knot.', '2020-09-25 10:28:50.000000', NULL, 1),
(7675375, 1254606, 65234, '<td valign="top">This looks like it was very complex to create.</td>', 'This looks like it was very complex to create.', '2020-09-25 10:32:04.000000', NULL, 1),
(7675376, 1254580, 65234, '<td valign="top">Kind of apocalyptic.</td>', 'Kind of apocalyptic.', '2020-09-25 10:32:58.000000', NULL, 1),
(7675378, 1254227, 65234, '<td valign="top">This may not be some people''s idea of an abstract but I love it! The hands sticking out are just fabulous. Pulling back the veil to reveal a prayer, maybe by a prisoner in handcuffs. So cool to explore and imagine.</td>', 'This may not be some people''s idea of an abstract but I love it! The hands sticking out are just fabulous. Pulling back the veil to reveal a prayer, maybe by a prisoner in handcuffs. So cool to explore and imagine.', '2020-09-25 10:48:19.000000', NULL, 1),
(7675379, 1254621, 65234, '<td valign="top">Can''t begin to imagine what the source image looked like LOL. But the result is really fun.</td>', 'Can''t begin to imagine what the source image looked like LOL. But the result is really fun.', '2020-09-25 10:48:42.000000', NULL, 1),
(7675380, 1254574, 65234, '<td valign="top">Looks like it''s flying.</td>', 'Looks like it''s flying.', '2020-09-25 10:48:50.000000', NULL, 1),
(7675381, 1254582, 65234, '<td valign="top">Those "arms" reaching out really draw my eye to the center, and add a nice compositional element.</td>', 'Those "arms" reaching out really draw my eye to the center, and add a nice compositional element.', '2020-09-25 10:49:13.000000', NULL, 1),
(7675387, 1254337, 138630, '<td valign="top">My favorite by quite a bit and my only 10.  Definitely something I would hang on my wall.  I like the tic tac toe title reference, but it''s also somehow very musical.  It reminds me of an instrument - one I would love to hear played by someone who knew and loved it well.</td>', 'My favorite by quite a bit and my only 10.  Definitely something I would hang on my wall.  I like the tic tac toe title reference, but it''s also somehow very musical.  It reminds me of an instrument - one I would love to hear played by someone who knew and loved it well.', '2020-09-25 13:09:49.000000', NULL, 1),
(7675388, 1254555, 138630, '<td valign="top">Stunning colors, mesmerizing flow and smoothness.  An exquisite result.  This would make a gorgeous, hand-blown, glass ornament . . . one which I might hang on my Christmas tree but also one that I would probably not put away after the holidays but would rather display on its own little stand on a coffee or end table.  9</td>', 'Stunning colors, mesmerizing flow and smoothness.  An exquisite result.  This would make a gorgeous, hand-blown, glass ornament . . . one which I might hang on my Christmas tree but also one that I would probably not put away after the holidays but would rather display on its own little stand on a coffee or end table.  9', '2020-09-25 13:12:29.000000', NULL, 1),
(7675389, 1254447, 138630, '<td valign="top">GREAT colors and I like the surprising combination of curved and angular a lot.  I think the title should have the word jewel or facet in it as this definitely reminds me of a beautifully cut precious stone.  8</td>', 'GREAT colors and I like the surprising combination of curved and angular a lot.  I think the title should have the word jewel or facet in it as this definitely reminds me of a beautifully cut precious stone.  8', '2020-09-25 13:13:55.000000', NULL, 1),
(7675390, 1254575, 138630, '<td valign="top">This one is so much fun and the title increased the pleasure for me.  I''m not one who buys fancy coffees, but I do appreciate good presentation.  And the suggestion of mocha and cream make this one very tempting.  8</td>', 'This one is so much fun and the title increased the pleasure for me.  I''m not one who buys fancy coffees, but I do appreciate good presentation.  And the suggestion of mocha and cream make this one very tempting.  8', '2020-09-25 13:16:34.000000', NULL, 1),
(7675391, 1254389, 138630, '<td valign="top">Dark but in a fascinating rather than morbid way and I love being able to recognize the original subject, both from the final image and in the title.  He does look more than a little surprised at what just happened to him!  8</td>', 'Dark but in a fascinating rather than morbid way and I love being able to recognize the original subject, both from the final image and in the title.  He does look more than a little surprised at what just happened to him!  8', '2020-09-25 13:18:03.000000', NULL, 1),
(7675392, 1254497, 138630, '<td valign="top">Another spider web one that I like a lot.  This looks like some sort or blueprint or maybe a celestial map - following it is for explorers more intrepid than I am.  8</td>', 'Another spider web one that I like a lot.  This looks like some sort or blueprint or maybe a celestial map - following it is for explorers more intrepid than I am.  8', '2020-09-25 13:20:12.000000', NULL, 1),
(7675393, 1254606, 138630, '<td valign="top">Great title - especially the "garden" bit as this reminds me of what one would get should one decide to impose the formality of a French on the charm of an English garden - and do it with the abandon only a riot of sunflowers can imagine.  8</td>', 'Great title - especially the "garden" bit as this reminds me of what one would get should one decide to impose the formality of a French on the charm of an English garden - and do it with the abandon only a riot of sunflowers can imagine.  8', '2020-09-25 13:23:07.000000', NULL, 1),
